// The poses, in the order of the PetPose enum below.
enum PetPose : uint8_t {
    POSE_ALERT = 0,
    POSE_HAPPY = 1,
    POSE_HUNGRY = 2,
    POSE_COUNT
};

static const uint16_t* const hd_pose_by_stage[POSE_COUNT][5] = {
    { hd_egg_alert, hd_pup_alert, hd_beast_alert, hd_gremlin_alert, hd_sentinel_alert },
    { hd_egg_happy, hd_pup_happy, hd_beast_happy, hd_gremlin_happy, hd_sentinel_happy },
    { hd_egg_hungry, hd_pup_hungry, hd_beast_hungry, hd_gremlin_hungry, hd_sentinel_hungry },
};

// Never null, and both indices clamped rather than trusted: this is read
// on every home-screen repaint, and a stage byte from a corrupt save must
// not index off the front of the table. Same shape as getStageHomeHD().
inline const uint16_t* getStagePoseHD(PetStage stage, PetPose pose) {
    int s = (int)stage - (int)STAGE_EGG;
    if (s < 0) s = 0;
    if (s > 4) s = 4;
    int p = (int)pose;
    if (p < 0 || p >= (int)POSE_COUNT) p = 0;
    return hd_pose_by_stage[p][s];
}
